proof fn always_double<T>(ex: Execution<T>, p: TempPred<T>)
    requires always(p).satisfied_by(ex),
    ensures always(always(p)).satisfied_by(ex),
{
    // Unfold the definition of `always`.
    reveal(always);

    // After unfolding, `always(p).satisfied_by(ex)` is a universal fact.
    assert(forall |i: nat| #[trigger] always(p).satisfied_by(ex.suffix(i))) by {
        reveal(always);
        assert(forall |j: nat| #[trigger] p.satisfied_by(ex.suffix(i).suffix(j))) by {
            // From `always(p).satisfied_by(ex)`, we can get the fact for offset `j + i`.
            assert(p.satisfied_by(ex.suffix(j + i)));
            // And `ex.suffix(i).suffix(j)` is exactly `ex.suffix(j + i)`.
            assert(ex.suffix(i).suffix(j) == ex.suffix(j + i));
        };
    };
}

